// Normalise: drop placeholder keys, de-dupe within an id, drop entries left empty.
{
  const keep = (k) => !k.endsWith('-not') && !k.endsWith('-dup');
  for (let i = FILES.length - 1; i >= 0; i--) {
    const f = FILES[i];
    f[3] = [...new Set((f[3] ?? []).filter(keep))];
    f[4] = [...new Set((f[4] ?? []).filter(keep))];
    if (!f[3].length && !f[4].length) FILES.splice(i, 1);
  }
}


